"""Dataset handling for Lab 08 (fixed infrastructure - students do not edit this file).

Layout on disk (standard YOLO layout, stored in assets/dataset/)::

    assets/dataset/
      classes.txt            custom class names, one per line (global ids 80, 81, ...)
      images/train, images/val
      labels/train, labels/val   one .txt per image: "class cx cy w h" (normalised)
      inbox/                 imported / captured images that are not annotated yet
      data.yaml              generated before every training run

Class numbering: ids 0-79 are the COCO classes, so the first custom class is 80.
"""
from __future__ import annotations

import shutil
import uuid
import zlib
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

import cv2
import numpy as np
import yaml

from config import (
    COCO_CLASS_NAMES,
    DATASET_DIR,
    IMAGE_EXTENSIONS,
    MAX_IMAGE_SIDE,
    NUM_COCO_CLASSES,
    VAL_EVERY,
)


class DatasetError(Exception):
    """Raised for problems the user can fix (bad class name, empty dataset, ...)."""


# --------------------------------------------------------------------------- #
# Image helpers (unicode-safe on Windows)
# --------------------------------------------------------------------------- #
def read_image(path: Path | str) -> np.ndarray | None:
    try:
        data = np.fromfile(str(path), dtype=np.uint8)
        return cv2.imdecode(data, cv2.IMREAD_COLOR)
    except Exception:
        return None


def write_jpeg(path: Path | str, image: np.ndarray, quality: int = 92) -> None:
    ok, buffer = cv2.imencode(".jpg", image, [cv2.IMWRITE_JPEG_QUALITY, quality])
    if not ok:
        raise DatasetError(f"Could not encode image for {path}")
    buffer.tofile(str(path))


def limit_size(image: np.ndarray, max_side: int = MAX_IMAGE_SIDE) -> np.ndarray:
    height, width = image.shape[:2]
    longest = max(height, width)
    if longest <= max_side:
        return image
    scale = max_side / longest
    return cv2.resize(
        image, (round(width * scale), round(height * scale)), interpolation=cv2.INTER_AREA
    )


# --------------------------------------------------------------------------- #
# Data classes
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Box:
    """Bounding box in normalised corner format. `cls` is the CUSTOM index (0 = id 80)."""

    cls: int
    x1: float
    y1: float
    x2: float
    y2: float

    def normalized(self) -> "Box":
        xa, xb = sorted((self.x1, self.x2))
        ya, yb = sorted((self.y1, self.y2))
        clamp = lambda v: min(1.0, max(0.0, v))  # noqa: E731
        return Box(self.cls, clamp(xa), clamp(ya), clamp(xb), clamp(yb))

    @property
    def width(self) -> float:
        return self.x2 - self.x1

    @property
    def height(self) -> float:
        return self.y2 - self.y1

    def is_valid(self, min_size: float = 0.005) -> bool:
        return self.width >= min_size and self.height >= min_size

    def to_yolo_line(self) -> str:
        cx = (self.x1 + self.x2) / 2
        cy = (self.y1 + self.y2) / 2
        return (
            f"{NUM_COCO_CLASSES + self.cls} "
            f"{cx:.6f} {cy:.6f} {self.width:.6f} {self.height:.6f}"
        )

    @staticmethod
    def from_yolo_line(line: str, num_custom: int) -> "Box | None":
        parts = line.split()
        if len(parts) != 5:
            return None
        try:
            class_id = int(float(parts[0]))
            cx, cy, w, h = (float(v) for v in parts[1:])
        except ValueError:
            return None
        custom = class_id - NUM_COCO_CLASSES
        if custom < 0 or custom >= num_custom:
            return None  # COCO ids / unknown ids are not editable in this tool
        return Box(custom, cx - w / 2, cy - h / 2, cx + w / 2, cy + h / 2).normalized()


@dataclass(frozen=True)
class ImageItem:
    path: Path
    location: str  # "inbox", "train" or "val"

    @property
    def name(self) -> str:
        return self.path.name

    @property
    def annotated(self) -> bool:
        return self.location != "inbox"


@dataclass(frozen=True)
class DatasetStats:
    train_images: int
    val_images: int
    inbox_images: int
    instances: tuple[int, ...]  # per custom class


# --------------------------------------------------------------------------- #
# Store
# --------------------------------------------------------------------------- #
class DatasetStore:
    def __init__(self, root: Path | str = DATASET_DIR):
        self.root = Path(root)
        self.ensure_structure()

    # ---- paths ---------------------------------------------------------- #
    @property
    def images_dir(self) -> Path:
        return self.root / "images"

    @property
    def labels_dir(self) -> Path:
        return self.root / "labels"

    @property
    def inbox_dir(self) -> Path:
        return self.root / "inbox"

    @property
    def classes_file(self) -> Path:
        return self.root / "classes.txt"

    @property
    def yaml_path(self) -> Path:
        return self.root / "data.yaml"

    def ensure_structure(self) -> None:
        for split in ("train", "val"):
            (self.images_dir / split).mkdir(parents=True, exist_ok=True)
            (self.labels_dir / split).mkdir(parents=True, exist_ok=True)
        self.inbox_dir.mkdir(parents=True, exist_ok=True)
        if not self.classes_file.exists():
            self.classes_file.write_text("", encoding="utf-8")

    def label_path(self, item: ImageItem) -> Path | None:
        if item.location == "inbox":
            return None
        return self.labels_dir / item.location / f"{item.path.stem}.txt"

    # ---- classes -------------------------------------------------------- #
    def classes(self) -> list[str]:
        text = self.classes_file.read_text(encoding="utf-8")
        return [line.strip() for line in text.splitlines() if line.strip()]

    def add_class(self, name: str) -> list[str]:
        cleaned = "_".join(name.strip().split())
        if not cleaned:
            raise DatasetError("Class name is empty.")
        if not all(ch.isalnum() or ch in "_-" for ch in cleaned):
            raise DatasetError("Use only letters, digits, '_' and '-' in class names.")
        existing = self.classes()
        if cleaned.lower() in (c.lower() for c in existing):
            raise DatasetError(f"Class '{cleaned}' already exists.")
        coco = {c.replace(" ", "_").lower() for c in COCO_CLASS_NAMES}
        if cleaned.lower() in coco:
            raise DatasetError(
                f"'{cleaned}' is already a COCO class. Pick a more specific name "
                f"(for example 'lab_{cleaned}')."
            )
        existing.append(cleaned)
        self.classes_file.write_text("\n".join(existing) + "\n", encoding="utf-8")
        return existing

    def class_usage(self, index: int) -> tuple[int, int]:
        """(number of boxes, number of images) that use custom class `index`."""
        boxes = images = 0
        for item in self.list_items():
            if not item.annotated:
                continue
            used = sum(1 for box in self.load_boxes(item) if box.cls == index)
            boxes += used
            images += 1 if used else 0
        return boxes, images

    def remove_class(self, index: int) -> tuple[int, int]:
        """Delete custom class `index` together with all of its boxes.

        Classes after it move up by one id (ids stay 80, 81, ... without gaps). Images
        whose last box disappears go back to the inbox, like in `save_boxes`.
        Returns (boxes removed, images moved back to the inbox).
        """
        names = self.classes()
        if not 0 <= index < len(names):
            raise DatasetError("This class does not exist.")
        removed_id = NUM_COCO_CLASSES + index
        removed = unannotated = 0
        for item in self.list_items():
            label = self.label_path(item)
            if label is None or not label.exists():
                continue
            kept: list[str] = []
            for line in label.read_text(encoding="utf-8").splitlines():
                parts = line.split()
                if len(parts) != 5:
                    continue
                try:
                    class_id = int(float(parts[0]))
                except ValueError:
                    continue
                if class_id == removed_id:
                    removed += 1
                    continue
                if class_id > removed_id:
                    parts[0] = str(class_id - 1)
                kept.append(" ".join(parts))
            if kept:
                label.write_text("\n".join(kept) + "\n", encoding="utf-8")
            else:
                label.unlink()
                destination = self._unique_path(self.inbox_dir, item.name)
                shutil.move(str(item.path), str(destination))
                unannotated += 1
        del names[index]
        self.classes_file.write_text("".join(f"{n}\n" for n in names), encoding="utf-8")
        return removed, unannotated

    def all_class_names(self) -> list[str]:
        """80 COCO names followed by the custom names (what the model is trained on)."""
        return list(COCO_CLASS_NAMES) + self.classes()

    # ---- listing -------------------------------------------------------- #
    @staticmethod
    def _images_in(directory: Path) -> list[Path]:
        if not directory.exists():
            return []
        return sorted(
            p for p in directory.iterdir()
            if p.is_file() and p.suffix.lower() in IMAGE_EXTENSIONS
        )

    def list_items(self) -> list[ImageItem]:
        items: list[ImageItem] = []
        for location, directory in (
            ("inbox", self.inbox_dir),
            ("train", self.images_dir / "train"),
            ("val", self.images_dir / "val"),
        ):
            items.extend(ImageItem(p, location) for p in self._images_in(directory))
        return items

    @staticmethod
    def split_for(name: str) -> str:
        return "val" if zlib.crc32(name.encode("utf-8")) % VAL_EVERY == 0 else "train"

    # ---- boxes ---------------------------------------------------------- #
    def load_boxes(self, item: ImageItem) -> list[Box]:
        label = self.label_path(item)
        if label is None or not label.exists():
            return []
        num_custom = len(self.classes())
        boxes = []
        for line in label.read_text(encoding="utf-8").splitlines():
            box = Box.from_yolo_line(line, num_custom)
            if box is not None and box.is_valid():
                boxes.append(box)
        return boxes

    def count_boxes(self, item: ImageItem) -> int:
        return len(self.load_boxes(item))

    @staticmethod
    def _unique_path(directory: Path, name: str) -> Path:
        candidate = directory / name
        stem, suffix = Path(name).stem, Path(name).suffix
        counter = 1
        while candidate.exists():
            candidate = directory / f"{stem}_{counter}{suffix}"
            counter += 1
        return candidate

    def save_boxes(self, item: ImageItem, boxes: list[Box]) -> ImageItem:
        """Write the boxes. Unannotated images move into train/val; images whose last
        box was removed go back to the inbox. Returns the (possibly moved) item."""
        boxes = [b.normalized() for b in boxes]
        boxes = [b for b in boxes if b.is_valid()]
        label = self.label_path(item)

        if not boxes:
            if item.location == "inbox":
                return item
            destination = self._unique_path(self.inbox_dir, item.name)
            shutil.move(str(item.path), str(destination))
            if label is not None and label.exists():
                label.unlink()
            return ImageItem(destination, "inbox")

        if item.location == "inbox":
            split = self.split_for(item.name)
            destination = self._unique_path(self.images_dir / split, item.name)
            shutil.move(str(item.path), str(destination))
            item = ImageItem(destination, split)
            label = self.label_path(item)

        assert label is not None
        label.parent.mkdir(parents=True, exist_ok=True)
        label.write_text("\n".join(b.to_yolo_line() for b in boxes) + "\n", encoding="utf-8")
        return item

    def delete_item(self, item: ImageItem) -> None:
        label = self.label_path(item)
        if item.path.exists():
            item.path.unlink()
        if label is not None and label.exists():
            label.unlink()

    def delete_items(self, items: list[ImageItem]) -> int:
        """Delete many images (and their labels) at once. Returns how many were deleted."""
        count = 0
        for item in items:
            if item.path.exists():
                self.delete_item(item)
                count += 1
        return count

    # ---- importing ------------------------------------------------------ #
    @staticmethod
    def _new_name() -> str:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        return f"custom_{stamp}_{uuid.uuid4().hex[:4]}.jpg"

    def add_frame(self, frame: np.ndarray) -> ImageItem:
        destination = self._unique_path(self.inbox_dir, self._new_name())
        write_jpeg(destination, limit_size(frame))
        return ImageItem(destination, "inbox")

    def import_images(self, paths: list[str]) -> tuple[list[ImageItem], int]:
        added: list[ImageItem] = []
        failed = 0
        for path in paths:
            image = read_image(path)
            if image is None:
                failed += 1
                continue
            added.append(self.add_frame(image))
        return added, failed

    # ---- stats / validation --------------------------------------------- #
    def stats(self) -> DatasetStats:
        counts = [0] * len(self.classes())
        train = val = inbox = 0
        for item in self.list_items():
            if item.location == "inbox":
                inbox += 1
                continue
            if item.location == "train":
                train += 1
            else:
                val += 1
            for box in self.load_boxes(item):
                counts[box.cls] += 1
        return DatasetStats(train, val, inbox, tuple(counts))

    def check_ready(self) -> tuple[list[str], list[str]]:
        """Return (errors, warnings). Errors block training."""
        errors: list[str] = []
        warnings: list[str] = []
        names = self.classes()
        stats = self.stats()
        if not names:
            errors.append("The dataset has no custom classes. Add one in Step 1.")
        if stats.train_images + stats.val_images == 0:
            errors.append("There are no annotated images. Annotate some images in Step 1.")
        for name, count in zip(names, stats.instances):
            if count == 0:
                warnings.append(f"Class '{name}' has no annotated boxes yet.")
        if stats.val_images == 0 and not errors:
            warnings.append("No validation images: the training images are used for validation.")
        if stats.inbox_images:
            warnings.append(f"{stats.inbox_images} image(s) are not annotated and will be ignored.")
        return errors, warnings

    def write_data_yaml(self) -> Path:
        """(Re)generate assets/dataset/data.yaml with absolute paths and 80 + N class names."""
        errors, _ = self.check_ready()
        if errors:
            raise DatasetError(errors[0])
        stats = self.stats()
        names = {i: name for i, name in enumerate(self.all_class_names())}
        config = {
            "path": self.root.resolve().as_posix(),
            "train": "images/train" if stats.train_images else "images/val",
            "val": "images/val" if stats.val_images else "images/train",
            "names": names,
        }
        self.yaml_path.write_text(
            "# Generated automatically before each training run - do not edit.\n"
            + yaml.safe_dump(config, sort_keys=False, allow_unicode=True),
            encoding="utf-8",
        )
        return self.yaml_path
